train = [([1, 1], 0), ([1, 3], 0),
         ([4, 2], 1), ([5, 3], 1)]

def feature(x):
    if len(x) != 2 or any(v < 0 for v in x):
        raise ValueError("Need two nonnegative counts")
    return max(0, x[0] + x[1])

def predict(x, threshold):
    return int(feature(x) >= threshold)

def mistakes(threshold):
    return sum(predict(x, threshold) != y
               for x, y in train)

candidates = [3, 5, 7]
best = min(candidates, key=lambda t: (mistakes(t), t))
assert best == 5
print([mistakes(t) for t in candidates])  # [1, 0, 1]
